/**
 * Ownership handover offers. Every read is filtered by `orgId`.
 */
import { and, eq, or } from "drizzle-orm";
import { newId } from "@/lib/id";
import { getDb, ownershipHandovers } from "@/server/db";
import { brandId, toIsoTimestamp } from "@/types/common";
import { orgPredicate } from "./base-repository";
import type { IsoTimestamp, OrgId, UserId } from "@/types/common";
import type {
  OwnershipHandover,
  OwnershipHandoverStatus,
} from "@/types/organization";

type Row = typeof ownershipHandovers.$inferSelect;

function toHandover(row: Row): OwnershipHandover {
  return {
    id: row.id,
    orgId: brandId<OrgId>(row.orgId),
    fromUserId: brandId<UserId>(row.fromUserId),
    toUserId: brandId<UserId>(row.toUserId),
    status: row.status,
    expiresAt: row.expiresAt as IsoTimestamp,
    createdAt: row.createdAt as IsoTimestamp,
    resolvedAt: row.resolvedAt as IsoTimestamp | null,
  };
}

/** The row still marked pending, which may already have lapsed. */
export async function findPendingRow(
  orgId: OrgId,
): Promise<OwnershipHandover | null> {
  const row = getDb()
    .select()
    .from(ownershipHandovers)
    .where(
      and(
        orgPredicate(ownershipHandovers.orgId, orgId),
        eq(ownershipHandovers.status, "pending"),
      ),
    )
    .get();
  return row ? toHandover(row) : null;
}

export async function insertHandover(
  orgId: OrgId,
  fromUserId: UserId,
  toUserId: UserId,
  createdAt: Date,
): Promise<OwnershipHandover> {
  const row = getDb()
    .insert(ownershipHandovers)
    .values({
      id: newId(),
      orgId,
      fromUserId,
      toUserId,
      status: "pending",
      expiresAt: toIsoTimestamp(new Date(createdAt.getTime() + 7 * 86_400_000)),
      createdAt: toIsoTimestamp(createdAt),
      resolvedAt: null,
    })
    .returning()
    .get();
  return toHandover(row);
}

export async function resolveHandover(
  orgId: OrgId,
  id: string,
  status: Exclude<OwnershipHandoverStatus, "pending">,
  at: Date,
): Promise<OwnershipHandover> {
  const row = getDb()
    .update(ownershipHandovers)
    .set({ status, resolvedAt: toIsoTimestamp(at) })
    .where(and(orgPredicate(ownershipHandovers.orgId, orgId), eq(ownershipHandovers.id, id)))
    .returning()
    .get();
  if (!row) throw new Error(`Ownership handover ${id} not found`);
  return toHandover(row);
}

/** Withdraws any open offer that involves `userId` on either side. */
export async function cancelPendingInvolving(
  orgId: OrgId,
  userId: UserId,
  at: Date,
): Promise<void> {
  getDb()
    .update(ownershipHandovers)
    .set({ status: "canceled", resolvedAt: toIsoTimestamp(at) })
    .where(
      and(
        orgPredicate(ownershipHandovers.orgId, orgId),
        eq(ownershipHandovers.status, "pending"),
        or(
          eq(ownershipHandovers.fromUserId, userId),
          eq(ownershipHandovers.toUserId, userId),
        ),
      ),
    )
    .run();
}
