/** Withdraws any open offer that involves `userId` on either side. */
export async function cancelPendingInvolving(
  orgId: OrgId,
  userId: UserId,
  at: Date,
): Promise<void> {
  getDb()
    .update(ownershipHandovers)
    .set({ status: "canceled", resolvedAt: toIsoTimestamp(at) })
    .where(
      and(
        orgPredicate(ownershipHandovers.orgId, orgId),
        eq(ownershipHandovers.status, "pending"),
        or(
          eq(ownershipHandovers.fromUserId, userId),
          eq(ownershipHandovers.toUserId, userId),
        ),
      ),
    )
    .run();
}
