/** The open offer, ignoring one that has lapsed. */
async function findOpenHandover(orgId: OrgId): Promise<OwnershipHandover | null> {
  const row = await handoverRepo.findPendingRow(orgId);
  if (row === null || new Date(row.expiresAt).getTime() <= Date.now()) return null;
  return row;
}

/** The pending offer addressed to the actor, refusing when absent or lapsed. */
async function requireOfferToActor(
  actor: Actor,
  orgId: OrgId,
): Promise<OwnershipHandover> {
  const row = await handoverRepo.findPendingRow(orgId);
  if (row === null || row.toUserId !== actor.userId) {
    throw new OwnershipHandoverError("nothing_pending");
  }
  if (new Date(row.expiresAt).getTime() <= Date.now()) {
    throw new OwnershipHandoverError("expired");
  }
  return row;
}

export async function initiateOwnershipHandover(
  actor: Actor,
  orgId: OrgId,
  toUserId: UserId,
): Promise<OwnershipHandover> {
  assertOrgScope(actor, orgId);
  const org = requireFound(await orgRepo.findOrgById(orgId), "Organization", orgId);
  assertRecordedOwner(actor, org);

  if (toUserId === actor.userId) throw new OwnershipHandoverError("self");

  const target = await memberRepo.findMember(orgId, toUserId);
  if (!target || target.status !== "active") {
    throw new NotFoundError("Member", toUserId);
  }

  if ((await findOpenHandover(orgId)) !== null) {
    throw new OwnershipHandoverError("pending_exists");
  }

  const now = new Date();
  const stale = await handoverRepo.findPendingRow(orgId);
  if (stale !== null) {
    await handoverRepo.resolveHandover(orgId, stale.id, "expired", now);
  }

  const handover = await handoverRepo.insertHandover(
    orgId,
    actor.userId,
    toUserId,
    now,
  );

  await notify(orgId, "ownership_handover", [toUserId], {
    title: "Ownership of the workspace was offered to you",
    body: `${actor.userId} offered you ownership of ${org.name}`,
    href: "/settings/organization",
    actorId: actor.userId,
  });

  return handover;
}

export async function acceptOwnershipHandover(
  actor: Actor,
  orgId: OrgId,
): Promise<Organization> {
  assertOrgScope(actor, orgId);
  const offer = await requireOfferToActor(actor, orgId);

  const fromUserId = offer.fromUserId;
  const newMember = requireFound(
    await memberRepo.findMember(orgId, actor.userId),
    "Member",
    actor.userId,
  );
  const oldMember = await memberRepo.findMember(orgId, fromUserId);

  // Promote first so the workspace has an owner at every instant.
  const promoted =
    newMember.role === "owner"
      ? null
      : await memberRepo.updateMemberRole(orgId, newMember.id, "owner");
  const demoted =
    oldMember && oldMember.role === "owner"
      ? await memberRepo.updateMemberRole(orgId, oldMember.id, "admin")
      : null;

  const org = await orgRepo.setOrgOwner(orgId, actor.userId);
  await handoverRepo.resolveHandover(orgId, offer.id, "accepted", new Date());

  if (promoted) {
    await emit("member.role_changed", {
      ...actorEnvelope(actor),
      memberId: promoted.id,
      from: newMember.role,
      to: "owner",
    });
  }
  if (demoted && oldMember) {
    await emit("member.role_changed", {
      ...actorEnvelope(actor),
      memberId: demoted.id,
      from: "owner",
      to: "admin",
    });
  }
  await emit("organization.ownership_transferred", {
    ...actorEnvelope(actor),
    fromUserId,
    toUserId: actor.userId,
  });

  return org;
}

export async function declineOwnershipHandover(
  actor: Actor,
  orgId: OrgId,
): Promise<OwnershipHandover> {
  assertOrgScope(actor, orgId);
  const offer = await requireOfferToActor(actor, orgId);
  return handoverRepo.resolveHandover(orgId, offer.id, "declined", new Date());
}

